const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (input.length === 0) return;

    const n = parseInt(input[0], 10);
    const m = parseInt(input[1], 10);

    const grid = Array.from({ length: n }, () => Array(m).fill(false));

    let ret = false;

    while (true) {
        let found = false;

        for (let i = 0; i < n && !found; i++) {
            for (let j = 0; j < m && !found; j++) {
                if (!grid[i][j]) {
                    for (let k = 0; k < n; k++) {
                        grid[k][j] = true;
                    }
                    for (let k = 0; k < m; k++) {
                        grid[i][k] = true;
                    }
                    found = true;
                }
            }
        }

        if (!found) {
            break;
        }

        ret = !ret;
    }

    if (!ret) {
        console.log("Malvika");
    } else {
        console.log("Akshat");
    }
}

